//! 🪄️ Bounded original GSUB single and multiple records preserve genuine captured font bytes.
use super::{FontLookup,super::{FontFace,FontProgress,FontReader,kerning::Index}};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct FontSubstitution{pub glyphs:[u16;64],pub count:usize}
semio_framework_value::artifact_retire_leaf!(FontSubstitution);
pub struct FontSubstitutionCursor{face:FontFace,lookup:FontLookup,byte_pointer:Option<usize>,glyph:u16,max_work:u64,phase:u8,sub:usize,at:usize,format:u16,probe:Option<Index>,sequence:usize,index:usize,output:Option<FontSubstitution>,work:u64,cancelled:bool,failure:Option<String>}
impl RetireOwned for FontSubstitutionCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.failure.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.failure.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontSubstitutionCursor{
 pub fn new(face:FontFace,lookup:FontLookup,glyph:u16,max_work:u64)->Self{let invalid=face.gsub.is_none()||!matches!(lookup.kind,1|2)||lookup.flags!=0&&lookup.flags!=8||!(1..=1000000000).contains(&max_work);Self{face,lookup,byte_pointer:None,glyph,max_work,phase:0,sub:0,at:0,format:0,probe:None,sequence:0,index:0,output:None,work:0,cancelled:false,failure:invalid.then(||"Invalid font substitution authority".into())}}
 fn step(&mut self,bytes:&[u8])->Result<(),String>{if bytes.len()!=self.face.byte_length||self.byte_pointer.is_some_and(|pointer|pointer!=bytes.as_ptr()as usize){return Err("Captured font substitution source changed".into());}self.byte_pointer=Some(bytes.as_ptr()as usize);let r=FontReader::new(bytes,self.face.gsub.ok_or("Font substitution authority missing")?)?;match self.phase{
  0=>{if self.sub==self.lookup.subtables{self.phase=3;return Ok(());}self.at=self.lookup.offset+usize::from(r.u16(self.lookup.offset+6+self.sub*2)?);self.format=r.u16(self.at)?;if if self.lookup.kind==1{!matches!(self.format,1|2)}else{self.format!=1}{return Err("Unsupported font substitution format".into());}self.probe=Some(Index::new(r,self.at+usize::from(r.u16(self.at+2)?),self.glyph,false)?);self.phase=1;},
  1=>{if !self.probe.as_mut().unwrap().step(r)?{return Ok(());}let coverage=self.probe.as_ref().unwrap().result();self.probe=None;if coverage<0{self.sub+=1;self.phase=0;return Ok(());}if self.lookup.kind==1&&self.format==1{let glyph=self.glyph.wrapping_add(r.i16(self.at+4)?as u16);if glyph>=self.face.glyphs{return Err("Font substitute glyph exceeds authority".into());}let mut glyphs=[0;64];glyphs[0]=glyph;self.output=Some(FontSubstitution{glyphs,count:1});self.phase=3;return Ok(());}let count=usize::from(r.u16(self.at+4)?);if coverage as usize>=count{return Err("Font substitution coverage exceeds authority".into());}if self.lookup.kind==1{let glyph=r.u16(self.at+6+coverage as usize*2)?;if glyph>=self.face.glyphs{return Err("Font substitute glyph exceeds authority".into());}let mut glyphs=[0;64];glyphs[0]=glyph;self.output=Some(FontSubstitution{glyphs,count:1});self.phase=3;return Ok(());}self.sequence=self.at+usize::from(r.u16(self.at+6+coverage as usize*2)?);let count=usize::from(r.u16(self.sequence)?);if count>64{return Err("Font multiple substitute limit exceeded".into());}r.range(self.sequence+2,count*2)?;self.output=Some(FontSubstitution{glyphs:[0;64],count});self.phase=2;},
  2=>{let output=self.output.as_mut().unwrap();if self.index==output.count{self.phase=3;return Ok(());}let glyph=r.u16(self.sequence+2+self.index*2)?;if glyph>=self.face.glyphs{return Err("Font substitute glyph exceeds authority".into());}output.glyphs[self.index]=glyph;self.index+=1;},
  _=>return Err("Font substitution stage invalid".into()),
 }Ok(())}
 pub fn advance(&mut self,bytes:&[u8],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid font substitution work grant".into());}if self.cancelled{return Err("Font substitution cancelled".into());}if let Some(error)=&self.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==3{break;}if self.work==self.max_work{self.failure=Some("Font substitution work limit exceeded".into());return Err(self.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes){self.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{0=>"subtable",1=>"coverage",2=>"replacement",_=>"complete"},work:self.work,done:self.phase==3})}
 pub fn result(&self)->Result<Option<FontSubstitution>,String>{if self.phase!=3||self.cancelled||self.failure.is_some(){return Err("Font substitution incomplete".into());}Ok(self.output)}
 pub fn cancel(&mut self){self.cancelled=true;}
}
